{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the primary objective of this packing plan — are you trying to minimize the total number of containers used, maximize the total weight of goods packed, or achieve some other goal?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options that constitute one semantic question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a fixed, known number of containers available for this shipment, or is the number of containers a decision variable that can be any non-negative integer?"
  ],
  "rationale": "The response asks a single clarification question regarding the nature of the container count (fixed vs. variable), which constitutes one independent semantic request."
}

{
